-- ============================================================================
-- Vendora demo seed - GENERATED by scripts/generate-seed.ts, do not edit by hand.
--   node --experimental-strip-types scripts/generate-seed.ts
-- Covers identities, stores, categories, catalog and the store settings the vendor
-- workspace edits. Transactional demo data (orders, deliveries, payouts) is created
-- through the RPCs so it stays consistent with the money columns.
-- ============================================================================

begin;

-- 1. Auth users for the one-click demo personas (password: demo1234).
insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at) values
  ('821e8ec7-5e22-4475-84ee-09ca7dd41b69', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'customer@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Sarah Customer', 'full_name', 'Sarah Customer'), now(), now()),
  ('a3843f15-38d7-4990-86a5-0fab5eadce28', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'newuser@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Alex Potential Vendor', 'full_name', 'Alex Potential Vendor'), now(), now()),
  ('34f31c91-c748-4476-87b1-f44a9b18ce01', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'vendor@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Marcus Tech Seller', 'full_name', 'Marcus Tech Seller'), now(), now()),
  ('6545faea-dda6-483e-8d2f-2e04a059437c', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'vendor2@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Priya Design Seller', 'full_name', 'Priya Design Seller'), now(), now()),
  ('f9099374-0044-4592-8755-294873addd8c', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'admin@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Elena Administrator', 'full_name', 'Elena Administrator'), now(), now()),
  ('1285904a-f682-471f-88b6-e2379ebbf6e0', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'support@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Jordan Support Lead', 'full_name', 'Jordan Support Lead'), now(), now()),
  ('3bcd334d-9b97-472d-8e45-74d806e454b4', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'rider@demo.test', extensions.crypt('demo1234', extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('name', 'Sam Express Rider', 'full_name', 'Sam Express Rider'), now(), now())
on conflict (id) do update set
  email = excluded.email,
  encrypted_password = excluded.encrypted_password,
  email_confirmed_at = now();

-- GoTrue reads these fields into non-nullable Go strings, so a NULL left behind by a
  -- raw INSERT makes every password login for that user fail with HTTP 500
  -- "Database error querying schema". Write the same empty strings GoTrue itself writes.
update auth.users
   set confirmation_token = coalesce(confirmation_token, ''),
       recovery_token = coalesce(recovery_token, ''),
       reauthentication_token = coalesce(reauthentication_token, ''),
       email_change_token_new = coalesce(email_change_token_new, ''),
       email_change_token_current = coalesce(email_change_token_current, ''),
       email_change = coalesce(email_change, ''),
       phone_change = coalesce(phone_change, ''),
       phone_change_token = coalesce(phone_change_token, '');

-- An email login needs its identity row; GoTrue creates it alongside the user.
insert into auth.identities (id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
select extensions.gen_random_uuid(),
       u.id::text,
       u.id,
       jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
       'email',
       now(),
       now(),
       now()
  from auth.users u
 where not exists (select 1 from auth.identities i where i.provider_id = u.id::text and i.provider = 'email');

-- handle_new_user() created the profiles; grant each persona its roles.
update public.profiles set roles = array['customer'::public.user_role]::public.user_role[], vendor_status = 'none'::public.vendor_status where id = '821e8ec7-5e22-4475-84ee-09ca7dd41b69';
update public.profiles set roles = array['customer'::public.user_role]::public.user_role[], vendor_status = 'none'::public.vendor_status where id = 'a3843f15-38d7-4990-86a5-0fab5eadce28';
update public.profiles set roles = array['customer'::public.user_role, 'vendor'::public.user_role]::public.user_role[], vendor_status = 'approved'::public.vendor_status where id = '34f31c91-c748-4476-87b1-f44a9b18ce01';
update public.profiles set roles = array['customer'::public.user_role, 'vendor'::public.user_role]::public.user_role[], vendor_status = 'approved'::public.vendor_status where id = '6545faea-dda6-483e-8d2f-2e04a059437c';
update public.profiles set roles = array['admin'::public.user_role, 'customer'::public.user_role]::public.user_role[], vendor_status = 'none'::public.vendor_status where id = 'f9099374-0044-4592-8755-294873addd8c';
update public.profiles set roles = array['support'::public.user_role]::public.user_role[], vendor_status = 'none'::public.vendor_status where id = '1285904a-f682-471f-88b6-e2379ebbf6e0';
update public.profiles set roles = array['rider'::public.user_role]::public.user_role[], vendor_status = 'none'::public.vendor_status where id = '3bcd334d-9b97-472d-8e45-74d806e454b4';

